using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "DeitysPactAction", menuName = "Data/Battle/Battle Actions/Orion/DeitysPact Action")]
public class DeitysPactAction : MultiStarAction
{
	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (starAbilityReference.Value == devotionOrbStarAbility)
		{
			CastTarget(target, source);
			return;
		}
		GetBattleAction().CastTargetAmount(target, amount, source);
		CheckMoveOrb(source);
	}
}
